G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   Rule @900.0: not converted: source '$$ Management Servers': an alias, whose value is set per engine, and the input holds no engine; not converted: destination '$$ Local Cluster': an alias, whose value is set per engine, and the input holds no engine; references '$$ Management Servers': an alias, whose value is s
#   old block: disabled in the source
#   internal zone out: the source of the rule is in zone Internal, and a rule of Network Firewall names no zone: give the networks behind Internal with --zone-network
#   not to dmz: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (pub-web, 192.168.10.10)
#   updates by name: the addresses of the destination 'updates.example.com (names)' are not known; a rule of Network Firewall names addresses
#   zone or web host out: the source of the rule is in zone Internal, and a rule of Network Firewall names no zone: give the networks behind Internal with --zone-network; the destination of the rule is in zone External, and a rule of Network Firewall names no zone: give the networks behind External with --zone-network
#   zone or web host out (2): the destination of the rule is in zone External, and a rule of Network Firewall names no zone: give the networks behind External with --zone-network
#   vpn only: not converted: it matches traffic of VPNs only (Source VPN)
#   no social: no port mapping for application(s) Facebook; supply one with --app-map
#   helpdesk to dmz: source user match helpdesk is not converted
#   unfinished: disabled in the source
#   office web: schedule 'Office hours' is not converted; the rule would apply at all times
#   block list: not converted: it has a block list (it discards what the dynamic block list holds, and lets the rest go on)

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
